{
  "packs": [
    "local/shepherd",
    {
      "id": "basics",
      "version": "60904.3",
      "via": [
        "core"
      ]
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60904.1"
    },
    {
      "id": "git-github",
      "version": "60903.1",
      "via": [
        "basics"
      ]
    },
    {
      "id": "claude-code-web-users-support",
      "version": "60902.1",
      "answers": {
        "store": "missingbulb/Shepherd"
      },
      "config": {
        "repo": "missingbulb/Shepherd"
      }
    },
    {
      "id": "claudinite-growth",
      "version": "60904.4"
    },
    {
      "id": "tidy-repo",
      "version": "60903.3"
    },
    {
      "id": "claudinite-fleet-sheepdog",
      "version": "60903.2",
      "config": {
        "owner": "missingbulb",
        "kind": "user",
        "exclude": [
          "missingbulb/empty",
          "missingbulb/Sheepdog"
        ],
        "canonRepo": "missingbulb/Claudinite",
        "staleDays": 14,
        "packSeeds": [
          {
            "id": "claude-code-web-users-support",
            "config": {
              "repo": "missingbulb/Shepherd"
            }
          }
        ]
      }
    },
    {
      "id": "claudinite-dashboard",
      "version": "60902.15",
      "answers": {
        "mode": "fleet — this deployment is the overview across every repo under missingbulb, enumerated in the browser as the viewer"
      },
      "config": {
        "mode": "fleet",
        "canonRepo": "missingbulb/Claudinite",
        "owner": "missingbulb",
        "exclude": [
          "missingbulb/empty"
        ]
      }
    },
    {
      "id": "claudinite-tasks",
      "version": "60904.2"
    }
  ],
  "taskScheduler": {
    "agenticTaskInvocationEndpoints": {
      "default": {
        "url": "[REDACTED:env:SESSION_INGRESS_URL]/v1/claude_code/routines/trig_01Xc43XQwqjUgTaFQhXvAJdk/fire",
        "tokenSecret": "CCR_ROUTINE_TOKEN"
      }
    },
    "dailyHour": 4,
    "weeklyDay": "Sun",
    "monthlyDay": 1
  },
  "engineVersion": "60902.1"
}

